  bool get isOk => this is Ok<T, E>;

  /// Whether this is an [Err] result.
  bool get isErr => this is Err<T, E>;

  /// The success value, or `null` when this is an [Err].
  T? get valueOrNull => switch (this) {
    Ok<T, E>(:final value) => value,
    Err<T, E>() => null,
