  /// [ShellExecOptions.timeout] and [ShellExecOptions.cancelToken] still
  /// apply (both stop the job).
  Future<Result<ShellJob, ExecutionError>> startShellJob(
    String command, {
    required String id,
    required String logPath,
    ShellExecOptions? options,
  });
}

